/*
 * C3 Ambient Lamp v0.1.0
 * Target: ESP32-C3 SuperMini / ESP32C3 Dev Module (Arduino ESP32 core 2.x/3.x)
 *
 * GPIO3  <- touch I/O (TTP223, active HIGH)
 * GPIO4  <-> I2C SDA (AHT20 + BMP280)
 * GPIO5  <-> I2C SCL
 * GPIO6  -> PWM logic output (to a correctly sized LED driver)
 * 3V3/GND -> sensor and touch power (if their modules support 3.3V)
 *
 * No third-party libraries: Wire, WiFi, WebServer and Preferences
 * come with Arduino-ESP32.
 *
 * Wi-Fi setup AP: C3-Lamp-Setup / LampSetup26!
 * Setup URL: http://192.168.4.1/
 * Long touch (>= 6 s): reopen Wi-Fi setup AP (does not erase saved network).
 *
 * Changing the duty cycle changes brightness; PWM frequency stays fixed.
 */

#include <Arduino.h>
#include <Wire.h>
#include <WiFi.h>
#include <WebServer.h>
#include <Preferences.h>
#include <time.h>
#include <math.h>

// ---------------- USER CONFIGURATION ----------------
static constexpr uint8_t PIN_TOUCH = 3;
static constexpr uint8_t PIN_SDA = 4;
static constexpr uint8_t PIN_SCL = 5;
static constexpr uint8_t PIN_LED_PWM = 6;
static constexpr uint8_t TOUCH_ACTIVE_LEVEL = HIGH;
static constexpr bool INVERT_PWM = false; // true only for an active-LOW driver

static constexpr uint32_t PWM_FREQUENCY = 2000;
static constexpr uint8_t PWM_BITS = 10;
static constexpr uint16_t PWM_MAX_DUTY = (1U << PWM_BITS) - 1U;
static constexpr uint8_t LED_BRIGHTNESS_DAY = 100;   // 08:00-17:59
static constexpr uint8_t LED_BRIGHTNESS_EVENING = 50; // 18:00-22:59
static constexpr uint8_t LED_BRIGHTNESS_NIGHT = 10;   // 23:00-07:59
static constexpr uint32_t FADE_DURATION_MS = 650;
static constexpr uint32_t SENSOR_INTERVAL_MS = 5000;
static constexpr uint32_t TOUCH_DEBOUNCE_MS = 35;
static constexpr uint32_t TOUCH_HOLD_SETUP_MS = 6000;

static const char *AP_SSID = "C3-Lamp-Setup";
static const char *AP_PASSWORD = "LampSetup26!";
static const char *TZ_ROME = "CET-1CEST,M3.5.0/2,M10.5.0/3";

// ---------------- SHARED STATE ----------------
static WebServer server(80);
static Preferences prefs;
static String savedSsid;
static String savedPassword;
static bool setupApActive = false;
static uint32_t connectedSinceMs = 0;
static uint32_t apOpenedMs = 0;
static uint32_t lastWifiAttemptMs = 0;
static bool timeServiceStarted = false;
static bool wifiPreviouslyConnected = false;

static bool lightsOn = false;
static uint8_t scheduledBrightness = LED_BRIGHTNESS_NIGHT;
static uint16_t pwmCurrentDuty = 0;
static uint16_t pwmStartDuty = 0;
static uint16_t pwmTargetDuty = 0;
static uint32_t fadeStartMs = 0;
static uint32_t lastPwmUpdateMs = 0;

static bool touchLastRaw = false;
static bool touchStable = false;
static bool touchLongHandled = false;
static uint32_t touchLastEdgeMs = 0;
static uint32_t touchStartMs = 0;

static float ahtTemperatureC = NAN;
static float ahtHumidityPercent = NAN;
static float bmpTemperatureC = NAN;
static float bmpPressureHpa = NAN;
static bool ahtPresent = false;
static bool bmpPresent = false;
static bool ahtPending = false;
static uint32_t ahtStartedMs = 0;
static uint32_t lastSensorCycleMs = 0;
static uint8_t bmpAddress = 0;

struct BmpCalibration {
  uint16_t t1;
  int16_t t2, t3;
  uint16_t p1;
  int16_t p2, p3, p4, p5, p6, p7, p8, p9;
};
static BmpCalibration bmpCal;

// ---------------- BASIC UTILITIES ----------------
static bool wifiConnected() { return WiFi.status() == WL_CONNECTED; }

static void pwmWrite(uint16_t duty) {
  if (duty > PWM_MAX_DUTY) duty = PWM_MAX_DUTY;
  uint16_t output = INVERT_PWM ? (PWM_MAX_DUTY - duty) : duty;
#if defined(ESP_ARDUINO_VERSION_MAJOR) && ESP_ARDUINO_VERSION_MAJOR >= 3
  ledcWrite(PIN_LED_PWM, output);
#else
  ledcWrite(0, output);
#endif
}

static String jsonEscape(const String &s) {
  String out;
  out.reserve(s.length() + 8);
  for (size_t i = 0; i < s.length(); ++i) {
    unsigned char c = (unsigned char)s[i];
    if (c == '"' || c == '\\') { out += '\\'; out += (char)c; }
    else if (c == '\n') out += F("\\n");
    else if (c == '\r') out += F("\\r");
    else if (c == '\t') out += F("\\t");
    else if (c < 0x20) out += '?';
    else out += (char)c;
  }
  return out;
}

static String jsonNumberOrNull(float number, uint8_t decimals = 1) {
  return isfinite(number) ? String(number, decimals) : String("null");
}

static bool getLocalTimeSafe(struct tm &out) {
  time_t current = time(nullptr);
  if (current < 1735689600) return false; // Prior to 2025 => not synced
  return localtime_r(&current, &out) != nullptr;
}

static const char *periodName() {
  struct tm now;
  if (!getLocalTimeSafe(now)) return "unsynced";
  if (now.tm_hour >= 8 && now.tm_hour < 18) return "day";
  if (now.tm_hour >= 18 && now.tm_hour < 23) return "evening";
  return "night";
}

static uint8_t brightnessForTime() {
  struct tm now;
  if (!getLocalTimeSafe(now)) return LED_BRIGHTNESS_NIGHT;
  if (now.tm_hour >= 8 && now.tm_hour < 18) return LED_BRIGHTNESS_DAY;
  if (now.tm_hour >= 18 && now.tm_hour < 23) return LED_BRIGHTNESS_EVENING;
  return LED_BRIGHTNESS_NIGHT;
}

// ---------------- LED BRIGHTNESS & FADE ----------------
static void setPwmTarget(uint16_t newTarget, uint32_t now) {
  if (newTarget == pwmTargetDuty) return;
  pwmStartDuty = pwmCurrentDuty;
  pwmTargetDuty = newTarget;
  fadeStartMs = now;
}

static void updateLighting(uint32_t now) {
  scheduledBrightness = brightnessForTime();
  uint16_t target = lightsOn ? (uint16_t)((uint32_t)PWM_MAX_DUTY * scheduledBrightness / 100U) : 0;
  setPwmTarget(target, now);
  if ((uint32_t)(now - lastPwmUpdateMs) < 15U) return;
  lastPwmUpdateMs = now;

  uint32_t elapsed = now - fadeStartMs;
  if (elapsed >= FADE_DURATION_MS) {
    pwmCurrentDuty = pwmTargetDuty;
  } else {
    float t = (float)elapsed / (float)FADE_DURATION_MS;
    float eased = t * t * (3.0f - 2.0f * t);
    float value = (float)pwmStartDuty + ((float)pwmTargetDuty - (float)pwmStartDuty) * eased;
    pwmCurrentDuty = (uint16_t)lroundf(value);
  }
  pwmWrite(pwmCurrentDuty);
}

// ---------------- WIFI SETUP & RECOVERY ----------------
static void openSetupAccessPoint() {
  if (setupApActive) return;
  WiFi.mode(WIFI_AP_STA);
  setupApActive = WiFi.softAP(AP_SSID, AP_PASSWORD);
  apOpenedMs = millis();
  Serial.println(setupApActive ? F("[WiFi] Setup AP active: C3-Lamp-Setup / 192.168.4.1")
                               : F("[WiFi] Failed to start setup AP"));
}

static void startStationConnection() {
  if (savedSsid.length() == 0) return;
  WiFi.mode(setupApActive ? WIFI_AP_STA : WIFI_STA);
  WiFi.begin(savedSsid.c_str(), savedPassword.c_str());
  lastWifiAttemptMs = millis();
  Serial.print(F("[WiFi] Connecting to "));
  Serial.println(savedSsid);
}

static void updateWifi(uint32_t now) {
  bool connected = wifiConnected();
  if (connected) {
    if (!wifiPreviouslyConnected) {
      connectedSinceMs = now;
      Serial.print(F("[WiFi] Connected. IP: "));
      Serial.println(WiFi.localIP().toString());
      configTzTime(TZ_ROME, "pool.ntp.org", "time.google.com", "time.cloudflare.com");
      timeServiceStarted = true;
    }
    if (setupApActive && (uint32_t)(now - apOpenedMs) > 120000U) {
      WiFi.softAPdisconnect(true);
      setupApActive = false;
      WiFi.mode(WIFI_STA);
      Serial.println(F("[WiFi] Setup AP disabled; connected on home network"));
    }
  } else if (savedSsid.length()) {
    if (!setupApActive && (uint32_t)(now - lastWifiAttemptMs) > 15000U) openSetupAccessPoint();
    if ((uint32_t)(now - lastWifiAttemptMs) > 20000U) startStationConnection();
  }
  wifiPreviouslyConnected = connected;
}

// ---------------- TOUCH: TAP ON/OFF, LONG HOLD SETUP ----------------
static void updateTouch(uint32_t now) {
  bool raw = (digitalRead(PIN_TOUCH) == TOUCH_ACTIVE_LEVEL);
  if (raw != touchLastRaw) {
    touchLastRaw = raw;
    touchLastEdgeMs = now;
  }
  if (raw != touchStable && (uint32_t)(now - touchLastEdgeMs) >= TOUCH_DEBOUNCE_MS) {
    touchStable = raw;
    if (touchStable) {
      touchStartMs = now;
      touchLongHandled = false;
    } else if (!touchLongHandled && (uint32_t)(now - touchStartMs) < TOUCH_HOLD_SETUP_MS) {
      lightsOn = !lightsOn;
      Serial.println(lightsOn ? F("[Touch] Lights ON") : F("[Touch] Lights OFF"));
    }
  }
  if (touchStable && !touchLongHandled && (uint32_t)(now - touchStartMs) >= TOUCH_HOLD_SETUP_MS) {
    touchLongHandled = true;
    openSetupAccessPoint();
    Serial.println(F("[Touch] Hold detected: Wi-Fi setup enabled"));
  }
}

// ---------------- I2C & AHT20 ----------------
static bool i2cWrite(uint8_t addr, uint8_t reg, uint8_t value) {
  Wire.beginTransmission(addr);
  Wire.write(reg);
  Wire.write(value);
  return Wire.endTransmission() == 0;
}

static bool i2cRead(uint8_t addr, uint8_t startReg, uint8_t *buffer, size_t count) {
  Wire.beginTransmission(addr);
  Wire.write(startReg);
  if (Wire.endTransmission(false) != 0) return false;
  if ((size_t)Wire.requestFrom((int)addr, (int)count) != count) return false;
  for (size_t i = 0; i < count; i++) buffer[i] = Wire.read();
  return true;
}

static bool initAht20() {
  Wire.beginTransmission(0x38);
  if (Wire.endTransmission() != 0) return false;
  // Soft initialization (AHT20/AHT21). This does not affect BMP280.
  Wire.beginTransmission(0x38);
  Wire.write(0xBE);
  Wire.write(0x08);
  Wire.write(0x00);
  bool ok = Wire.endTransmission() == 0;
  return ok;
}

static bool startAht20Measurement(uint32_t now) {
  Wire.beginTransmission(0x38);
  Wire.write(0xAC);
  Wire.write(0x33);
  Wire.write(0x00);
  if (Wire.endTransmission() != 0) return false;
  ahtStartedMs = now;
  ahtPending = true;
  return true;
}

static void finishAht20Measurement(uint32_t now) {
  if (!ahtPending || (uint32_t)(now - ahtStartedMs) < 85U) return;
  ahtPending = false;
  uint8_t raw[7] = {0};
  // Seven bytes on AHT20 (includes CRC; CRC not used here).
  uint8_t n = (uint8_t)Wire.requestFrom((int)0x38, 7);
  if (n < 6) {
    ahtTemperatureC = ahtHumidityPercent = NAN;
    return;
  }
  for (uint8_t i = 0; i < n && i < 7; i++) raw[i] = Wire.read();
  if (raw[0] & 0x80) return; // Sensor busy: keep last valid measurements

  uint32_t hum20 = ((uint32_t)raw[1] << 12) | ((uint32_t)raw[2] << 4) | (raw[3] >> 4);
  uint32_t temp20 = ((uint32_t)(raw[3] & 0x0F) << 16) | ((uint32_t)raw[4] << 8) | raw[5];
  float rh = (float)hum20 * 100.0f / 1048576.0f;
  float tc = (float)temp20 * 200.0f / 1048576.0f - 50.0f;
  if (rh >= 0.0f && rh <= 100.0f && tc > -50.0f && tc < 150.0f) {
    ahtHumidityPercent = rh;
    ahtTemperatureC = tc;
  }
}

// ---------------- BMP280 READING & COMPENSATION ----------------
static uint16_t u16le(const uint8_t *b) {
  return (uint16_t)b[0] | ((uint16_t)b[1] << 8);
}
static int16_t s16le(const uint8_t *b) { return (int16_t)u16le(b); }

static bool initBmp280At(uint8_t addr) {
  uint8_t chipId;
  if (!i2cRead(addr, 0xD0, &chipId, 1) || chipId != 0x58) return false;
  uint8_t cal[24];
  if (!i2cRead(addr, 0x88, cal, sizeof(cal))) return false;
  bmpCal.t1 = u16le(cal + 0);
  bmpCal.t2 = s16le(cal + 2);
  bmpCal.t3 = s16le(cal + 4);
  bmpCal.p1 = u16le(cal + 6);
  bmpCal.p2 = s16le(cal + 8);
  bmpCal.p3 = s16le(cal + 10);
  bmpCal.p4 = s16le(cal + 12);
  bmpCal.p5 = s16le(cal + 14);
  bmpCal.p6 = s16le(cal + 16);
  bmpCal.p7 = s16le(cal + 18);
  bmpCal.p8 = s16le(cal + 20);
  bmpCal.p9 = s16le(cal + 22);
  if (bmpCal.p1 == 0) return false;
  bmpAddress = addr;
  // ctrl_meas: temperature x1, pressure x1, normal mode.
  // config: standby 1000ms, IIR filter x4.
  return i2cWrite(addr, 0xF5, 0xA8) && i2cWrite(addr, 0xF4, 0x27);
}

static bool readBmp280() {
  if (!bmpPresent) return false;
  uint8_t raw[6];
  if (!i2cRead(bmpAddress, 0xF7, raw, sizeof(raw))) return false;
  int32_t adcP = ((int32_t)raw[0] << 12) | ((int32_t)raw[1] << 4) | ((int32_t)raw[2] >> 4);
  int32_t adcT = ((int32_t)raw[3] << 12) | ((int32_t)raw[4] << 4) | ((int32_t)raw[5] >> 4);
  if (adcP == 0x80000 || adcT == 0x80000) return false;

  // Bosch BMP280 reference compensation formulas, using double precision.
  double v1 = ((double)adcT / 16384.0 - (double)bmpCal.t1 / 1024.0) * bmpCal.t2;
  double a = (double)adcT / 131072.0 - (double)bmpCal.t1 / 8192.0;
  double v2 = a * a * bmpCal.t3;
  double tFine = v1 + v2;
  double temp = tFine / 5120.0;

  v1 = tFine / 2.0 - 64000.0;
  v2 = v1 * v1 * bmpCal.p6 / 32768.0;
  v2 += v1 * bmpCal.p5 * 2.0;
  v2 = v2 / 4.0 + bmpCal.p4 * 65536.0;
  v1 = (bmpCal.p3 * v1 * v1 / 524288.0 + bmpCal.p2 * v1) / 524288.0;
  v1 = (1.0 + v1 / 32768.0) * bmpCal.p1;
  if (fabs(v1) < 0.00000001) return false;
  double pressurePa = 1048576.0 - adcP;
  pressurePa = (pressurePa - v2 / 4096.0) * 6250.0 / v1;
  v1 = bmpCal.p9 * pressurePa * pressurePa / 2147483648.0;
  v2 = pressurePa * bmpCal.p8 / 32768.0;
  pressurePa += (v1 + v2 + bmpCal.p7) / 16.0;

  if (temp < -45.0 || temp > 90.0 || pressurePa < 30000.0 || pressurePa > 120000.0) return false;
  bmpTemperatureC = (float)temp;
  bmpPressureHpa = (float)(pressurePa / 100.0);
  return true;
}

static void updateSensors(uint32_t now) {
  finishAht20Measurement(now);
  if ((uint32_t)(now - lastSensorCycleMs) < SENSOR_INTERVAL_MS) return;
  lastSensorCycleMs = now;
  if (bmpPresent) {
    if (!readBmp280()) bmpTemperatureC = bmpPressureHpa = NAN;
  }
  if (ahtPresent && !ahtPending) {
    if (!startAht20Measurement(now)) ahtTemperatureC = ahtHumidityPercent = NAN;
  }
}

// ---------------- LOCAL HTTP SERVER ----------------
static String statusJson() {
  struct tm now;
  bool hasTime = getLocalTimeSafe(now);
  String result;
  result.reserve(480);
  result += F("{\"firmware\":\"0.1.0\",\"wifi_connected\":");
  result += (wifiConnected() ? "true" : "false");
  result += F(",\"wifi_ssid\":\""); result += jsonEscape(wifiConnected() ? WiFi.SSID() : savedSsid); result += '"';
  result += F(",\"ip\":\""); result += (wifiConnected() ? WiFi.localIP().toString() : ""); result += '"';
  result += F(",\"ap_active\":"); result += (setupApActive ? "true" : "false");
  result += F(",\"time\":");
  if (hasTime) {
    char dateBuffer[26];
    strftime(dateBuffer, sizeof(dateBuffer), "%Y-%m-%d %H:%M:%S", &now);
    result += '"'; result += dateBuffer; result += '"';
  } else result += "null";
  result += F(",\"period\":\""); result += periodName(); result += '"';
  result += F(",\"lights_on\":"); result += (lightsOn ? "true" : "false");
  result += F(",\"brightness_percent\":"); result += String(lightsOn ? scheduledBrightness : 0);
  result += F(",\"scheduled_brightness_percent\":"); result += String(scheduledBrightness);
  result += F(",\"temperature_c\":"); result += jsonNumberOrNull(ahtTemperatureC);
  result += F(",\"humidity_percent\":"); result += jsonNumberOrNull(ahtHumidityPercent);
  result += F(",\"bmp_temperature_c\":"); result += jsonNumberOrNull(bmpTemperatureC);
  result += F(",\"pressure_hpa\":"); result += jsonNumberOrNull(bmpPressureHpa, 2);
  result += F(",\"aht20_found\":"); result += (ahtPresent ? "true" : "false");
  result += F(",\"bmp280_found\":"); result += (bmpPresent ? "true" : "false");
  result += "}";
  return result;
}

static void sendStatusJson() {
  // Read-only API intended for a future PC companion on the home LAN.
  server.sendHeader("Access-Control-Allow-Origin", "*");
  server.sendHeader("Cache-Control", "no-store");
  server.send(200, "application/json; charset=utf-8", statusJson());
}

