static void onWifiForm() {
  if (!setupApActive) { server.send(403, "text/plain", "Enable setup via long touch (6s) first."); return; }
  String newSsid = server.arg("ssid");
  String newPassword = server.arg("password");
  newSsid.trim();
  if (!newSsid.length() || newSsid.length() > 32 || newPassword.length() > 63) {
    server.send(400, "text/plain", "Invalid Wi-Fi SSID/password length."); return;
  }
  prefs.putString("ssid", newSsid);
  prefs.putString("pwd", newPassword);
  savedSsid = newSsid;
  savedPassword = newPassword;
  server.send(200, "text/html; charset=utf-8",
              "<html><meta charset='utf-8'><body><h2>Rete salvata!</h2>"
              "<p>L'ESP32 prova a collegarsi. Torna sulla rete di casa e apri l'IP "
              "dell'ESP32 che trovi nel router oppure nel monitor seriale.</p></body></html>");
  startStationConnection();
}

static void initServer() {
  server.on("/", HTTP_GET, []() { server.send_P(200, "text/html; charset=utf-8", HOME_HTML); });
  server.on("/api/status", HTTP_GET, sendStatusJson);
  server.on("/api/toggle", HTTP_POST, []() {
    lightsOn = !lightsOn;
    sendStatusJson();
  });
  server.on("/wifi", HTTP_POST, onWifiForm);
  server.onNotFound([]() { server.send(404, "text/plain", "Not found"); });
  server.begin();
}

// ---------------- ESP32 ENTRY POINTS ----------------
void setup() {
  Serial.begin(115200);
  pinMode(PIN_TOUCH, INPUT);
  touchLastRaw = (digitalRead(PIN_TOUCH) == TOUCH_ACTIVE_LEVEL);
  touchStable = touchLastRaw;
  touchLastEdgeMs = millis();
  touchStartMs = millis();

#if defined(ESP_ARDUINO_VERSION_MAJOR) && ESP_ARDUINO_VERSION_MAJOR >= 3
  bool pwmReady = ledcAttach(PIN_LED_PWM, PWM_FREQUENCY, PWM_BITS);
#else
  bool pwmReady = (ledcSetup(0, PWM_FREQUENCY, PWM_BITS) != 0);
  ledcAttachPin(PIN_LED_PWM, 0);
#endif
  pwmWrite(0);
  Serial.println(F("\n[C3 Ambient Lamp] v0.1.0"));
  if (!pwmReady) Serial.println(F("[LED] WARNING: PWM setup failed"));

  Wire.begin(PIN_SDA, PIN_SCL);
  Wire.setClock(100000);
  ahtPresent = initAht20();
  bmpPresent = initBmp280At(0x76) || initBmp280At(0x77);
  Serial.printf("[I2C] AHT20=%s BMP280=%s\n", ahtPresent ? "yes" : "no", bmpPresent ? "yes" : "no");

  prefs.begin("c3lamp", false);
  savedSsid = prefs.getString("ssid", "");
  savedPassword = prefs.getString("pwd", "");
  WiFi.setAutoReconnect(true);
  if (savedSsid.length() == 0) openSetupAccessPoint();
  else startStationConnection();
  initServer();

  // The first sensor read starts immediately; the touch remains responsive.
  lastSensorCycleMs = millis();
}

void loop() {
  uint32_t now = millis();
  updateTouch(now);
  updateLighting(now);
  updateWifi(now);
  updateSensors(now);
  server.handleClient();
  yield();
}
